  '.oc{--oc-panel:var(--panel);--oc-bg:#12161d;--oc-line:rgba(160,172,196,.22);--oc-accent:var(--brass);--oc-muted:var(--muted);--oc-ink:var(--ink)}' +
  '@media (prefers-reduced-motion:no-preference){a,.play{transition:color .15s,background-color .15s}}';

// Right-to-left scripts. /rules has been served in Arabic, Hebrew, Persian and
// Urdu for a while with nothing but <html lang>, which lays the page out
// left-to-right: punctuation lands on the wrong side and list markers sit
// opposite the text. The language alone is enough to know better.
var SEO_RTL_LANGS = ['ar', 'he', 'fa', 'ur'];
function _seoIsRtl(lang) { return SEO_RTL_LANGS.indexOf(String(lang || '')) !== -1; }

// Internal links carry the current language forward, but only to a page that
