    try { fs.readdirSync(exDir).forEach(function (f) { if (/^(plate|self|preview|bg|frame|img[0-9]?)\.(png|svg|webp|jpe?g)$/i.test(f) || f === 'seat.json' || f === 'style.css') cp(f, path.join(dest, f)); }); } catch (e) {}
